import{_ as o,c as a,o as r,a3 as s}from"./chunks/framework.Dk6sf0Ip.js";const m=JSON.parse('{"title":"Guía de Uso del Reporte COMPRAS","description":"","frontmatter":{},"headers":[],"relativePath":"reportes/COMPRAS_maestro.md","filePath":"reportes/COMPRAS_maestro.md","lastUpdated":1759238350000}'),t={name:"reportes/COMPRAS_maestro.md"};function i(l,e,n,d,c,u){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="guia-de-uso-del-reporte-compras" tabindex="-1"><strong>Guía de Uso del Reporte COMPRAS</strong> <a class="header-anchor" href="#guia-de-uso-del-reporte-compras" aria-label="Permalink to &quot;**Guía de Uso del Reporte COMPRAS**&quot;">​</a></h1><p>El reporte <strong>COMPRAS</strong> es una herramienta diseñada para ayudarte a visualizar y analizar información relacionada con las compras realizadas en el sistema. Este documento te guiará paso a paso sobre cómo usarlo, entenderlo y sacarle el máximo provecho.</p><h2 id="tabla-de-contenidos" tabindex="-1"><strong>Tabla de Contenidos</strong> <a class="header-anchor" href="#tabla-de-contenidos" aria-label="Permalink to &quot;**Tabla de Contenidos**&quot;">​</a></h2><ol><li><a href="#descripción-general">Descripción General</a></li><li><a href="#parámetros-del-reporte">Parámetros del Reporte</a></li><li><a href="#estructura-del-reporte">Estructura del Reporte</a></li><li><a href="#cómo-interpretar-los-datos">Cómo Interpretar los Datos</a></li><li><a href="#casos-de-uso-comunes">Casos de Uso Comunes</a></li><li><a href="#consejos-y-mejores-prácticas">Consejos y Mejores Prácticas</a></li><li><a href="#preguntas-frecuentes-faq">Pregunstas frecuentes (FAQ)</a></li></ol><hr><h2 id="descripcion-general" tabindex="-1"><strong>Descripción General</strong> <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;**Descripción General**&quot;">​</a></h2><p>El reporte <strong>COMPRAS</strong> proporciona un desglose detallado de todas las compras realizadas dentro de un rango de fechas específico. Incluye información sobre:</p><ul><li>Los artículos comprados.</li><li>Las cantidades y precios unitarios.</li><li>Los ajustes aplicados y los impuestos correspondientes.</li><li>El total de cada compra agrupado por fecha y referencia.</li><li>Proveedores</li></ul><p>Este reporte es ideal para análisis financieros, seguimiento de inventario y auditorías.</p><hr><h2 id="parametros-del-reporte" tabindex="-1"><strong>Parámetros del Reporte</strong> <a class="header-anchor" href="#parametros-del-reporte" aria-label="Permalink to &quot;**Parámetros del Reporte**&quot;">​</a></h2><p>Antes de ejecutar el reporte, puedes configurar los siguientes parámetros para personalizar los resultados:</p><table tabindex="0"><thead><tr><th>Parámetro</th><th>Descripción</th><th>Ejemplo de Valor</th></tr></thead><tbody><tr><td><code>nro_secuencia</code></td><td>Filtra las compras por número de secuencia. Deja en blanco para incluir todas las secuencias.</td><td><code>123</code></td></tr><tr><td><code>flowid</code></td><td>Identificador del flujo de trabajo asociado a las compras.</td><td><code>11013</code> (Compras)</td></tr><tr><td><code>tipo_articulo</code></td><td>Filtra las compras por categoría de artículo. Deja en blanco para incluir todas las categorías.</td><td><code>&quot;Electrónica&quot;</code></td></tr><tr><td><code>fechaDesde</code></td><td>Fecha inicial del rango de búsqueda. Deja en blanco si no quieres filtrar por fechas.</td><td><code>2023-01-01</code></td></tr><tr><td><code>fechaHasta</code></td><td>Fecha final del rango de búsqueda. Deja en blanco si no quieres filtrar por fechas.</td><td><code>2023-12-31</code></td></tr><tr><td><code>proveedor</code></td><td>Filtra las compras por nombre del proveedor. Usa coincidencias parciales(No discrimina por mayusculas o minusculas). Deja en blanco si no quieres filtrar por proveedor.</td><td><code>&quot;Proveedor ABC&quot;</code></td></tr><tr><td><code>internalcode</code></td><td>Filtra las compras por código interno del artículo, traera toda la compra donde esta este articulo. Usa coincidencias parciales.</td><td><code>&quot;INT123&quot;</code></td></tr><tr><td><code>externalcode</code></td><td>Filtra las compras por código externo del artículo, traera toda la compra donde esta este articulo.. Usa coincidencias parciales.</td><td><code>&quot;EXT456&quot;</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>flowid: ID que representa un flujo de trabajo. En este contexto, se refiere al proceso de compras. Imp. Alic: Porcentaje de impuesto aplicado (por ejemplo, IVA).</p></div><h3 id="como-configurar-los-parametros" tabindex="-1"><strong>Cómo Configurar los Parámetros</strong> <a class="header-anchor" href="#como-configurar-los-parametros" aria-label="Permalink to &quot;**Cómo Configurar los Parámetros**&quot;">​</a></h3><ol><li>Abre el reporte.</li><li>Ingresa los valores deseados en los campos de parámetros. <ul><li>Para buscar por <strong>código interno</strong>, usa el parámetro <code>internalcode</code>.</li><li>Para buscar por <strong>código externo</strong>, usa el parámetro <code>externalcode</code>.</li></ul></li><li>Haz clic en <strong>&quot;APLICAR&quot;</strong> para ver los resultados.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Nota</strong>: Si no deseas filtrar por <code>internalcode</code> o <code>externalcode</code>, deja estos campos en blanco.</p></div><hr><h2 id="estructura-del-reporte" tabindex="-1"><strong>Estructura del Reporte</strong> <a class="header-anchor" href="#estructura-del-reporte" aria-label="Permalink to &quot;**Estructura del Reporte**&quot;">​</a></h2><p>El reporte está organizado en varias secciones para facilitar la interpretación de los datos:</p><h3 id="_1-encabezado" tabindex="-1"><strong>1. Encabezado</strong> <a class="header-anchor" href="#_1-encabezado" aria-label="Permalink to &quot;**1. Encabezado**&quot;">​</a></h3><ul><li>Muestra el título del reporte: <strong>&quot;COMPRAS&quot;</strong>.</li><li>Proporciona una vista general del contenido.</li></ul><h3 id="_2-agrupaciones" tabindex="-1"><strong>2. Agrupaciones</strong> <a class="header-anchor" href="#_2-agrupaciones" aria-label="Permalink to &quot;**2. Agrupaciones**&quot;">​</a></h3><p>El reporte organiza los datos en dos niveles de agrupación:</p><ul><li><strong>Por Referencia</strong>: Cada grupo muestra el número de referencia y el número de secuencia.</li><li><strong>Por Fecha</strong>: Dentro de cada referencia, los datos se agrupan por fecha de compra.</li></ul><h3 id="_3-columnas-de-datos" tabindex="-1"><strong>3. Columnas de Datos</strong> <a class="header-anchor" href="#_3-columnas-de-datos" aria-label="Permalink to &quot;**3. Columnas de Datos**&quot;">​</a></h3><p>Las columnas disponibles son:</p><table tabindex="0"><thead><tr><th>Columna</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>Internalcode/Externalcode</strong></td><td>Codigos de los articulos.</td></tr><tr><td><strong>Descripción</strong></td><td>Nombre del artículo comprado.</td></tr><tr><td><strong>Cantidad</strong></td><td>Cantidad de unidades compradas.</td></tr><tr><td><strong>Precio Unitario</strong></td><td>Precio unitario del artículo.</td></tr><tr><td><strong>Precio Total</strong></td><td>Total antes de ajustes e impuestos.</td></tr><tr><td><strong>Importe Ajuste</strong></td><td>Porcentaje de ajuste aplicado al precio total.</td></tr><tr><td><strong>Imp. Alic</strong></td><td>Porcentaje de impuesto aplicado (IVA).</td></tr><tr><td><strong>Importe Final</strong></td><td>Total final después de ajustes e impuestos.</td></tr></tbody></table><h3 id="_4-totales" tabindex="-1"><strong>4. Totales</strong> <a class="header-anchor" href="#_4-totales" aria-label="Permalink to &quot;**4. Totales**&quot;">​</a></h3><ul><li>Al final de cada grupo de fecha, se muestra el <strong>Total de la compra</strong> para ese día.</li><li>Estos totales son útiles para realizar análisis rápidos.</li></ul><hr><h2 id="como-interpretar-los-datos" tabindex="-1"><strong>Cómo Interpretar los Datos</strong> <a class="header-anchor" href="#como-interpretar-los-datos" aria-label="Permalink to &quot;**Cómo Interpretar los Datos**&quot;">​</a></h2><h3 id="_1-identificar-compras-por-proveedor" tabindex="-1"><strong>1. Identificar Compras por Proveedor</strong> <a class="header-anchor" href="#_1-identificar-compras-por-proveedor" aria-label="Permalink to &quot;**1. Identificar Compras por Proveedor**&quot;">​</a></h3><ul><li>Usa el filtro <code>proveedor</code> para encontrar todas las compras realizadas con un proveedor específico.</li><li>Observa los totales diarios para identificar patrones de gasto.</li></ul><h3 id="_2-identificar-compras-por-codigo-interno-o-externo" tabindex="-1"><strong>2. Identificar Compras por Código Interno o Externo</strong> <a class="header-anchor" href="#_2-identificar-compras-por-codigo-interno-o-externo" aria-label="Permalink to &quot;**2. Identificar Compras por Código Interno o Externo**&quot;">​</a></h3><ul><li><p>Usa el filtro <code>internalcode</code> para encontrar compras relacionadas con un código interno específico.</p></li><li><p>Usa el filtro <code>externalcode</code> para encontrar compras relacionadas con un código externo específico.</p></li><li><p>Observa los totales diarios para identificar patrones de gasto.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>💡 Si estás buscando un artículo específico, usar el código interno suele ser más preciso que el nombre o descripción.</p></div></li></ul><h3 id="_3-analizar-impuestos-y-ajustes" tabindex="-1"><strong>3. Analizar Impuestos y Ajustes</strong> <a class="header-anchor" href="#_3-analizar-impuestos-y-ajustes" aria-label="Permalink to &quot;**3. Analizar Impuestos y Ajustes**&quot;">​</a></h3><ul><li>La columna <strong>Imp. Alic</strong> muestra el porcentaje de impuesto aplicado.</li><li>La columna <strong>Importe Ajuste</strong> indica si se aplicó un descuento o recargo adicional.</li></ul><h3 id="_4-seguimiento-de-inventarios" tabindex="-1"><strong>4. Seguimiento de Inventarios</strong> <a class="header-anchor" href="#_4-seguimiento-de-inventarios" aria-label="Permalink to &quot;**4. Seguimiento de Inventarios**&quot;">​</a></h3><ul><li>La columna <strong>Cantidad</strong> te permite verificar cuántas unidades de un artículo se han comprado.</li><li>Combina esto con la columna <strong>Descripción</strong> para identificar tendencias en la demanda de productos.</li></ul><hr><h2 id="casos-de-uso-comunes" tabindex="-1"><strong>Casos de Uso Comunes</strong> <a class="header-anchor" href="#casos-de-uso-comunes" aria-label="Permalink to &quot;**Casos de Uso Comunes**&quot;">​</a></h2><h3 id="_1-auditoria-de-gastos" tabindex="-1"><strong>1. Auditoría de Gastos</strong> <a class="header-anchor" href="#_1-auditoria-de-gastos" aria-label="Permalink to &quot;**1. Auditoría de Gastos**&quot;">​</a></h3><ul><li>Usa los filtros <code>fechaDesde</code> y <code>fechaHasta</code> para revisar las compras realizadas en un período específico.</li><li>Verifica los totales diarios para asegurarte de que coincidan con los registros contables.</li></ul><h3 id="_2-analisis-de-proveedores" tabindex="-1"><strong>2. Análisis de Proveedores</strong> <a class="header-anchor" href="#_2-analisis-de-proveedores" aria-label="Permalink to &quot;**2. Análisis de Proveedores**&quot;">​</a></h3><ul><li>Aplica el filtro <code>proveedor</code> para evaluar el desempeño de un proveedor específico.</li><li>Compara los totales de compra entre diferentes proveedores.</li></ul><h3 id="_3-control-de-inventarios" tabindex="-1"><strong>3. Control de Inventarios</strong> <a class="header-anchor" href="#_3-control-de-inventarios" aria-label="Permalink to &quot;**3. Control de Inventarios**&quot;">​</a></h3><ul><li>Utiliza la columna <strong>Cantidad</strong> para monitorear el volumen de compras de cada artículo.</li><li>Identifica artículos con altos volúmenes de compra para optimizar el inventario.</li></ul><hr><h2 id="consejos-y-mejores-practicas" tabindex="-1"><strong>Consejos y Mejores Prácticas</strong> <a class="header-anchor" href="#consejos-y-mejores-practicas" aria-label="Permalink to &quot;**Consejos y Mejores Prácticas**&quot;">​</a></h2><ol><li><p><strong>Usa Filtros Específicos</strong>: Si trabajas con grandes volúmenes de datos, utiliza todos los filtros disponibles para reducir el número de resultados y mejorar el rendimiento.</p></li><li><p><strong>Exporta los Resultados</strong>: Guarda el reporte en formato PDF o Excel para compartirlo con otros miembros del equipo o para realizar análisis adicionales.</p></li><li><p><strong>Revisa Regularmente</strong>: Usa este reporte periódicamente para mantener un control constante sobre las compras y detectar posibles irregularidades.</p></li></ol><hr><h2 id="preguntas-frecuentes-faq" tabindex="-1">Preguntas frecuentes (FAQ) <a class="header-anchor" href="#preguntas-frecuentes-faq" aria-label="Permalink to &quot;Preguntas frecuentes (FAQ)&quot;">​</a></h2><h3 id="¿que-pasa-si-no-aparece-ningun-resultado" tabindex="-1"><strong>¿Qué pasa si no aparece ningún resultado?</strong> <a class="header-anchor" href="#¿que-pasa-si-no-aparece-ningun-resultado" aria-label="Permalink to &quot;**¿Qué pasa si no aparece ningún resultado?**&quot;">​</a></h3><ul><li><strong>Respuesta</strong>: Si no aparecen resultados después de ejecutar el reporte, verifica lo siguiente: <ol><li>Asegúrate de que los filtros aplicados (como <code>fechaDesde</code>, <code>fechaHasta</code>, <code>proveedor</code>, <code>internalcode</code>, <code>externalcode</code>, etc.) sean correctos.</li><li>Comprueba que existan datos en el rango de fechas seleccionado.</li><li>Si usas filtros opcionales como <code>internalcode</code> o <code>externalcode</code>, asegúrate de que los valores ingresados coincidan exactamente con los registros en la base de datos.</li><li>Si el problema persiste, contacta al equipo de soporte para verificar la conexión a la base de datos o la consulta SQL.</li></ol></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>👉 Solución:</strong> Probá dejar algunos filtros en blanco y ejecutá el reporte nuevamente para confirmar si hay datos. Después podés ir refinando la búsqueda.</p></div><hr><h3 id="¿por-que-una-compra-no-muestra-ajustes" tabindex="-1"><strong>¿Por qué una compra no muestra ajustes?</strong> <a class="header-anchor" href="#¿por-que-una-compra-no-muestra-ajustes" aria-label="Permalink to &quot;**¿Por qué una compra no muestra ajustes?**&quot;">​</a></h3><ul><li><strong>Respuesta</strong>: Una compra puede no mostrar ajustes (<code>Importe Ajuste</code>) por las siguientes razones: <ol><li>No se aplicó ningún ajuste durante la creación de la compra.</li><li>El campo <code>porcentajuste</code> en la base de datos tiene un valor de <code>0</code> o está vacío.</li><li>El ajuste podría haber sido aplicado manualmente fuera del sistema.</li></ol></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Para verificar si hay ajustes, revisa la columna <code>porcentajuste</code>. Si el valor es <code>0</code>, significa que no se aplicó ningún ajuste.</p></div><hr><h3 id="¿puedo-usar-varios-filtros-a-la-vez" tabindex="-1"><strong>¿Puedo usar varios filtros a la vez?</strong> <a class="header-anchor" href="#¿puedo-usar-varios-filtros-a-la-vez" aria-label="Permalink to &quot;**¿Puedo usar varios filtros a la vez?**&quot;">​</a></h3><ul><li><strong>Respuesta</strong>: ¡Sí! Puedes combinar varios filtros para refinar los resultados. Por ejemplo: <ul><li>Filtra por <code>fechaDesde</code> y <code>fechaHasta</code> para un rango específico.</li><li>Agrega <code>proveedor</code> para buscar compras de un proveedor en particular.</li><li>Usa <code>internalcode</code> o <code>externalcode</code> para filtrar por artículos específicos.</li><li>Combina <code>tipo_articulo</code> con otros filtros para obtener resultados aún más precisos.</li></ul></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>📌 Importante:</strong> Cuantos más filtros uses, más específicos serán los resultados. Sin embargo, asegúrate de no excluir demasiados datos accidentalmente.<br><br></p></div><p>💡 Si no estás seguro de los resultados, prueba aplicando un filtro a la vez para ver cómo afecta la salida. :::</p><hr><h3 id="¿como-interpreto-los-totales-diarios" tabindex="-1"><strong>¿Cómo interpreto los totales diarios?</strong> <a class="header-anchor" href="#¿como-interpreto-los-totales-diarios" aria-label="Permalink to &quot;**¿Cómo interpreto los totales diarios?**&quot;">​</a></h3><ul><li><strong>Respuesta</strong>: Los totales diarios muestran el monto total de las compras realizadas en un día específico. Estos totales incluyen: <ol><li>El precio total antes de ajustes e impuestos.</li><li>Los ajustes aplicados (<code>Importe Ajuste</code>).</li><li>Los impuestos (<code>Imp. Alic</code>).</li></ol></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>💡 Si deseas comparar los gastos diarios, exporta el reporte a Excel y realiza un análisis adicional.</p></div><hr><h3 id="¿puedo-buscar-parte-de-un-nombre-o-codigo" tabindex="-1"><strong>¿Puedo buscar parte de un nombre o código?</strong> <a class="header-anchor" href="#¿puedo-buscar-parte-de-un-nombre-o-codigo" aria-label="Permalink to &quot;**¿Puedo buscar parte de un nombre o código?**&quot;">​</a></h3><p>Sí. Tanto los campos de <strong>proveedor</strong>, <strong>internalcode</strong> y <strong>externalcode</strong> admiten <strong>coincidencias parciales</strong>. Es decir, si escribís <code>&quot;ABC&quot;</code> como proveedor, el sistema buscará proveedores que contengan esas letras, como <code>&quot;Proveedor ABC S.A.&quot;</code>, <code>&quot;Distribuidora ABC&quot;</code> o <code>&quot;ABC Importaciones&quot;</code>.</p><hr><h3 id="¿que-significan-los-colores-alternados-en-las-filas" tabindex="-1"><strong>¿Qué significan los colores alternados en las filas?</strong> <a class="header-anchor" href="#¿que-significan-los-colores-alternados-en-las-filas" aria-label="Permalink to &quot;**¿Qué significan los colores alternados en las filas?**&quot;">​</a></h3><ul><li><strong>Respuesta</strong>: Los colores alternados en las filas (gris claro y blanco) están diseñados para mejorar la legibilidad del reporte. Esto facilita la identificación de cada registro individual.</li></ul><blockquote><p><strong>Nota</strong>: Esta funcionalidad está configurada automáticamente y no requiere ninguna acción por parte del usuario.</p></blockquote><hr><h3 id="¿por-que-algunos-campos-estan-vacios" tabindex="-1"><strong>¿Por qué algunos campos están vacíos?</strong> <a class="header-anchor" href="#¿por-que-algunos-campos-estan-vacios" aria-label="Permalink to &quot;**¿Por qué algunos campos están vacíos?**&quot;">​</a></h3><ul><li><strong>Respuesta</strong>: Algunos campos pueden estar vacíos debido a las siguientes razones: <ol><li>El dato no fue registrado en la base de datos (por ejemplo, <code>clientid</code> para prospectos nuevos).</li><li>El artículo no tiene un código interno (<code>internalcode</code>) o externo (<code>externalcode</code>) asignado.</li><li>No se aplicaron ajustes o impuestos a la compra.</li></ol></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>💡 Si encuentras muchos campos vacíos, verifica con el equipo de administración si los datos están completos en el sistema.</p></div><hr><p>Esperamos que esta guía te ayude a aprovechar al máximo el reporte <strong>COMPRAS</strong>. Si tienes preguntas adicionales o necesitas asistencia técnica, no dudes en contactar al equipo de soporte.</p>',82)]))}const g=o(t,[["render",i]]);export{m as __pageData,g as default};
